async function loadHsrProfile(){
  try{
    let profile=await Local.getLocal('profiles','hsr');
    if(!profile){
      const response=await fetch('assets/user/hsr-profile.json',{cache:'no-cache'});
      if(!response.ok) throw new Error('Profil HSR initial indisponible.');
      const text=await response.text();
      if(text.length>16*1024*1024) throw new Error('Le profil dépasse la limite locale de 16 Mo.');
      profile=JSON.parse(text);
      if(!Array.isArray(profile?.data?.avatar_list)) throw new Error('Format HoYoLAB non reconnu.');
      await Local.putLocal('profiles','hsr',profile);
    }
    state.hsrProfile=profile;
  }catch(error){state.profileError=error.message||'Import local indisponible.';}
  document.dispatchEvent(new Event('astralis:profile-ready'));
  return state.hsrProfile;
}
