const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const initials = name => { const words = String(name || 'A').replace(/\s*[·—-]\s*illustration$/i, '').trim().split(/\s+/).filter(Boolean); return (words.length > 1 ? words.slice(0, 2).map(w => w[0]).join('') : (words[0] || 'A').slice(0, 2)).toUpperCase(); };
// Keep the complete fallback chain: icon hosts differ in coverage between characters.
const avatarImage = (game, item) => imageSet(game, item, 'character');
const cardImage = (game, item) => game === 'gi' && item._category === 'character' ? (splashImage(game,item) || item.images?.cover1 || item.images?.card || imageSet(game,item)[0]) : imageSet(game, item)[0] || '';
const detailTitle = (item, game) => item?._name || GAMES[game].label;
window.astralisFallback = image => {
  try {
    const choices = JSON.parse(image.dataset.sources || '[]');
    const next = Number(image.dataset.index || '0') + 1;
    if (choices[next]) { image.dataset.index = String(next); image.src = choices[next]; }
    else {
      // Toutes les sources ont échoué : le glyphe neutre évite l’icône cassée du navigateur.
      image.closest('.art-frame,.unit-art,.gear-art,.detail-art,.skill-symbol')?.classList.add('is-missing');
      const stand = document.createElement('span');
      stand.className = `${image.className} art-fallback`.trim();
      stand.innerHTML = ic('image');
      stand.title = image.alt || '';
      image.replaceWith(stand);
    }
  } catch { image.remove(); }
};

function img(sources, className, alt = '', attrs = '') {
  const list = [...new Set((Array.isArray(sources) ? sources : [sources]).filter(Boolean))];
  if (!list.length) return `<span class="art-fallback ${className || ''}" title="Visuel indisponible">${ic('image')}</span>`;
  return `<img class="${className}" src="${esc(list[0])}" data-sources="${esc(JSON.stringify(list))}" data-index="0" alt="${esc(alt)}" loading="lazy" decoding="async" fetchpriority="low" onerror="window.astralisFallback(this)" ${attrs}>`;
}

function rarity(item) { return Number(item?.rarity ?? item?.max_rarity ?? item?.rank ?? item?.Stars ?? 0) || 0; }
function element(item) { return frenchTerm(item?.elementText || item?.element || item?.vision || item?.Element || item?.weaponText || item?.weapon || item?.weaponType || item?.type || item?.itemType || item?.item_sub_type || item?.path || item?.nation || 'Fiche'); }
function emblem(value) { return emblemIcon(value); }
function currentItems(section = state.section, game = state.game) {
  const category = categories[section];
  if (!category) return [];
  return state.catalogs[`${game}:${category}`] || [];
}
function statCount(game, kind) { return Object.keys(Store.ownedMap(game)).length; }

async function loadCatalog(game, category, { quiet = false } = {}) {
  const key = `${game}:${category}`;
  if (state.catalogs[key]) return state.catalogs[key];
  if (state.loaders.has(key)) return state.loaders.get(key);
  if (!quiet) state.loading = true;
  const job = Promise.resolve().then(async () => { try {
    const items = await catalog(game, category);
    state.catalogs[key] = items;
    state.catalogUpdated[key] = Date.now();
    return items;
  } catch (error) {
    state.dataError = error.message || 'La base communautaire ne répond pas.';
    return [];
  } finally {
    state.loading = false;
    state.loaders.delete(key);
    if (!quiet) render();
  }});
  state.loaders.set(key, job);
  return job;
}

async function preloadTeamCatalogs() {
  const game = state.game;
  await Promise.all(['character', 'weapon', 'artifact'].map(category => loadCatalog(game, category, { quiet: true })));
}

