function heroCount() {
  if (state.section === 'boosters') return '10';
  if (state.section === 'collection') return `${Object.values(binderInventory().owned).filter(n=>Number(n)>0).length}/${binderCards().length}`;
  if (state.section === 'teams') return Store.teams(state.game).length;
  if (state.section === 'notes') return Store.notes(state.game).length;
  if (state.section === 'tasks') return Store.tasks(state.game).filter(task=>!task.done).length;
  if (state.section === 'favorites') return Object.keys(Store.favorites()).filter(k => k.startsWith(`${state.game}:`)).length;
  if (state.section === 'media') return ic('arrow');
  if (state.section === 'builds') return readLocalList('astralis:gi:builds').filter(build=>build.character===state.buildCharacter).length;
  if (state.section === 'profile') return state.giProfile?.avatarInfoList?.length||0;
  if (state.section === 'tierlist') return state.tierStatus?.version||'—';
  if (state.section === 'dashboard') return ic('sparkle');
  if (state.section === 'customize' || state.section === 'optimizer' || state.section === 'data') return ic('arrow');
  return currentItems().length || '—';
}
