 const stack=(()=>{let node=document.querySelector('#assistant-toast-stack');if(!node){node=document.createElement('div');node.id='assistant-toast-stack';node.className='assistant-toast-stack';node.setAttribute('aria-live','polite');node.setAttribute('aria-label','Messages des compagnons');document.body.append(node);}return node;})();
 const accent=companionAccent(char)||'#a8d4ff',card=document.createElement('article');card.className='assistant-toast';card.style.setProperty('--nudge-accent',accent);card.style.setProperty('--toast-delay',`${delay}ms`);
 card.innerHTML=`${char?img(companionPortrait(char),'assistant-toast-avatar',char._name):'<span class="assistant-toast-avatar assistant-toast-glyph">✧</span>'}<div class="assistant-toast-copy"><header><b>${esc(char?._name||'Compagnon Astralis')}</b>${kind?`<small>${esc(kind)}</small>`:''}</header><p><span class="assistant-toast-typed"></span><i class="assistant-type-caret" aria-hidden="true"></i></p>${proposal?`<div class="assistant-proposal"><b>${esc(proposal.title)}</b><p>${esc(proposal.text)}</p><button type="button" data-assistant-accept>Accepter</button><button type="button" data-assistant-refuse>Pas maintenant</button></div>`:''}</div><button type="button" class="assistant-toast-close" aria-label="Fermer le message">×</button>`;
 stack.append(card);
 let timer=0,closed=false;const close=()=>{if(closed)return;closed=true;clearInterval(timer);card.classList.add('is-leaving');setTimeout(()=>{card.remove();if(!stack.children.length)stack.remove();},240);};
 card.querySelector('.assistant-toast-close')?.addEventListener('click',close);card.querySelector('[data-assistant-refuse]')?.addEventListener('click',close);card.querySelector('[data-assistant-accept]')?.addEventListener('click',()=>{close();if(proposal){state.section=proposal.section;state.query='';render();}});
 setTimeout(()=>{if(closed)return;const target=card.querySelector('.assistant-toast-typed');let index=0;const interval=Math.max(14,Math.min(34,1200/Math.max(40,String(text||'').length)));timer=setInterval(()=>{if(closed){clearInterval(timer);return;}target.textContent=String(text||'').slice(0,++index);if(index>=String(text||'').length){clearInterval(timer);card.classList.add('is-written');setTimeout(close,Math.max(10,Number(duration)||90)*1000);}},interval);},delay);
