 for(const relation of database.duos||[])if((relation.characters||[]).every(name=>activeNames.has(companionNameKey(name))))for(const conversation of relation.interactions||[])candidates.push({relation,conversation,kind:'Duo'});
 for(const [kind,key] of [['Trio','trios'],['Groupe','squads'],['Groupe de cinq','groupsOfFive']])for(const relation of database[key]||[])if((relation.characters||[]).every(name=>activeNames.has(companionNameKey(name))))for(const conversation of relation.conversations||[])candidates.push({relation,conversation,kind});
