 const recentKey='astralis:gi:companion-dialogue-recent';let recent=[];try{recent=JSON.parse(localStorage.getItem(recentKey)||'[]')}catch{}
 const fresh=candidates.filter(item=>!recent.includes(`${item.relation.id}:${item.conversation.id}`)),pool=fresh.length?fresh:candidates,choice=pool[Math.floor(Math.random()*pool.length)],token=`${choice.relation.id}:${choice.conversation.id}`;
 recent=[token,...recent.filter(item=>item!==token)].slice(0,12);localStorage.setItem(recentKey,JSON.stringify(recent));
 const byName=new Map(roster.map(row=>[companionNameKey(row.char._name),row])),duration=Math.max(10,Math.min(600,...roster.map(row=>Number(row.profile.messageDuration)||90)));
 const sourceLines=choice.conversation.messages||[],lines=sourceLines.map((message,index)=>({char:byName.get(companionNameKey(message.from))?.char,text:companionPersonalLine(message.text,message.from,message.to,choice.conversation.theme,choice.relation.context,token,index,database.personalities,sourceLines[index-1]?.text||'')})).filter(entry=>entry.char&&entry.text);
