function renderDashboardControls(){const key=`astralis:${state.game}:dashboard-widget-settings`;let saved={hidden:[],colors:{}};try{const parsed=JSON.parse(localStorage.getItem(key)||'{}');saved={...saved,...parsed};if(!Array.isArray(saved.hidden))saved.hidden=[];if(!saved.colors||typeof saved.colors!=='object')saved.colors={}}catch{}const labels={welcome:'Accueil',games:'Jeux', 'daily-team':'Équipe du jour','random-boss':'Boss du jour',checklist:'Checklist',companion:'Compagnon',events:'Événements','farm-builds':'Fiches de farm',profile:'Profil',metrics:'Statistiques',favorites:'Favoris',tools:'Conseils & raccourcis',next:'Prochaines étapes'};return `<details class="dashboard-builder"><summary>Disposition et widgets du tableau de bord</summary><div class="dashboard-builder-grid">${Object.entries(labels).map(([id,label])=>`<label><span>${esc(label)}</span><input type="checkbox" data-dashboard-visible="${id}" ${saved.hidden.includes(id)?'':'checked'}><input type="color" data-dashboard-color="${id}" value="${esc(saved.colors?.[id]||'#c8a5ff')}" aria-label="Couleur de ${esc(label)}"></label>`).join('')}</div><small>Déplace les blocs par glisser-déposer. Les choix de visibilité et de couleur sont propres à chaque jeu.</small></details>`;}

function renderNotes() {
  const all=Store.notes(state.game), entries=all.filter(note=>`${note.title} ${note.body} ${note.tag} ${note.targetName||''}`.toLowerCase().includes((state.query||'').toLowerCase())).sort((a,b)=>(Number(b.pinned)-Number(a.pinned))||(b.updated||0)-(a.updated||0));
  const tags=[...new Set(all.map(note=>note.tag||'NOTE'))];
  return `<div class="section-toolbar"><div><span class="eyebrow">MÉMOIRE DE TERRAIN · ${esc(GAMES[state.game].short.toUpperCase())}</span><h2>Mon carnet <span>${entries.length.toString().padStart(2,'0')}</span></h2><p>Plusieurs notes par personnage : builds, tests, rotations et idées personnelles.</p></div><button class="button-primary" data-action="new-note">${ic('plus')}<span>Nouvelle note</span></button></div><div class="journal-controls"><label class="search-box notes-search"><span>${ic('search')}</span><input id="notes-search" value="${esc(state.query)}" placeholder="Titre, personnage, note…"></label><select id="note-filter"><option value="all">Tous les types</option>${tags.map(tag=>`<option value="${esc(tag)}" ${state.noteFilter===tag?'selected':''}>${esc(tag)}</option>`).join('')}</select><span class="journal-counter">${all.filter(note=>note.pinned).length} épinglée(s)</span></div><div class="notes-grid">${entries.filter(note=>state.noteFilter==='all'||note.tag===state.noteFilter).length ? entries.filter(note=>state.noteFilter==='all'||note.tag===state.noteFilter).map(note=>`<article class="note-card ${note.pinned?'pinned':''}"><div class="note-meta"><span>${esc(note.tag||'NOTE')}</span><time>${new Date(note.updated||Date.now()).toLocaleDateString('fr-FR')}</time></div><h3>${esc(note.title)}</h3>${note.targetName?`<small class="note-character">${esc(note.targetName)}</small>`:''}<p>${esc(note.body)}</p><div class="note-actions"><button data-edit-note="${esc(note.id)}">Modifier</button><button data-pin-note="${esc(note.id)}">${note.pinned?'Désépingler':'Épingler'}</button><button data-delete-note="${esc(note.id)}">Supprimer</button></div></article>`).join('') : `<div class="empty-state"><span>${ic('notebook')}</span><b>Ton carnet est prêt</b><p>Crée une note générale ou ouvre la fiche d’un personnage pour lui associer des observations.</p></div>`}</div>`;
}

