function taskDateLabel(value){if(!value)return 'Sans échéance';const d=new Date(`${value}T12:00:00`);return d.toLocaleDateString('fr-FR',{day:'numeric',month:'short'});}
function renderTasks(){
  if(!state.catalogs[`${state.game}:character`]){loadCatalog(state.game,'character',{quiet:true}).then(render);return '<div class="loading-panel"><span class="loader"></span><b>Préparation de tes objectifs</b><p>Chargement des personnages pour lier les tâches aux bonnes fiches.</p></div>';}
  const all=Store.tasks(state.game), today=new Date().toISOString().slice(0,10), active=all.filter(t=>!t.done), overdue=active.filter(t=>t.due&&t.due<today), dueToday=active.filter(t=>t.due===today);
  let tasks=all.filter(task=>`${task.title} ${task.category} ${task.characterName||''}`.toLowerCase().includes((state.query||'').toLowerCase()));
  if(state.taskFilter==='active')tasks=tasks.filter(t=>!t.done);if(state.taskFilter==='done')tasks=tasks.filter(t=>t.done);if(state.taskFilter==='today')tasks=tasks.filter(t=>!t.done&&t.due===today);if(state.taskFilter==='overdue')tasks=tasks.filter(t=>!t.done&&t.due&&t.due<today);
  const rank={Urgente:0,Haute:1,Normale:2,Basse:3};tasks.sort((a,b)=>state.taskFilter==='priority'?(rank[a.priority]??2)-(rank[b.priority]??2):(a.due||'9999').localeCompare(b.due||'9999')||(b.updated||0)-(a.updated||0));
  const chars=state.catalogs[`${state.game}:character`]||[];
  return `<section class="task-summary"><article><small>À FAIRE</small><b>${active.length}</b><span>${all.length?`${Math.round((all.filter(t=>t.done).length/all.length)*100)} % terminées`:'Commence par un objectif simple'}</span></article><article class="${overdue.length?'has-overdue':''}"><small>EN RETARD</small><b>${overdue.length}</b><span>À reprendre quand tu veux</span></article><article><small>POUR AUJOURD’HUI</small><b>${dueToday.length}</b><span>${dueToday.length?'Échéance aujourd’hui':'Aucune échéance aujourd’hui'}</span></article><button class="button-primary" data-action="new-task">${ic('plus')}<span>Nouvelle tâche</span></button></section>
  <div class="section-toolbar task-toolbar"><div><span class="eyebrow">SUIVI PERSONNEL · ${esc(GAMES[state.game].short.toUpperCase())}</span><h2>Tout ce que tu veux terminer</h2><p>Filtre, trie, planifie et relie chaque objectif à un personnage.</p></div></div>
  <div class="task-controls"><label class="search-box"><span>${ic('search')}</span><input id="task-search" value="${esc(state.query)}" placeholder="Rechercher une tâche ou un personnage…"></label><div class="task-filters">${[['active','En cours'],['today','Aujourd’hui'],['overdue','En retard'],['done','Terminées'],['priority','Priorité']].map(([key,label])=>`<button class="quiet-btn ${state.taskFilter===key?'active':''}" data-task-filter="${key}">${label}${key==='overdue'&&overdue.length?` · ${overdue.length}`:''}</button>`).join('')}</div></div>
  <div class="task-layout"><section class="task-list">${tasks.length?tasks.map(task=>{const char=itemById(state.game,'character',task.character);return `<article class="task-card ${task.done?'is-done':''} priority-${(task.priority||'Normale').toLowerCase()}"><button class="task-check" data-task-toggle="${esc(task.id)}" aria-label="${task.done?'Réactiver':'Terminer'}">${task.done?ic('check'):''}</button><div class="task-main"><div class="task-card-meta"><span>${esc(task.category||'Objectif')}</span><i>·</i><span class="task-priority">${esc(task.priority||'Normale')}</span></div><h3>${esc(task.title)}</h3><div class="task-subline">${char?`<span>${esc(char._name)}</span>`:''}<time class="${!task.done&&task.due&&task.due<today?'late':''}">${taskDateLabel(task.due)}</time></div></div><div class="task-actions"><button data-task-edit="${esc(task.id)}" title="Modifier" aria-label="Modifier">${ic('pencil')}</button><button data-task-duplicate="${esc(task.id)}" title="Dupliquer" aria-label="Dupliquer">${ic('copy')}</button><button data-task-delete="${esc(task.id)}" title="Supprimer">×</button></div></article>`;}).join(''):`<div class="empty-state task-empty"><span>${ic('tasks')}</span><b>${state.taskFilter==='done'?'Rien de terminé ici pour le moment':'Tout est à jour.'}</b><p>Ajoute un petit objectif ou pars d’un modèle pour structurer ta prochaine session.</p><button class="button-primary" data-action="new-task">Créer une tâche</button></div>`}</section>
  <aside class="task-side"><span class="eyebrow">DÉMARRER EN UN CLIC</span><h3>Modèles utiles</h3><p>Chaque modèle crée une liste d’étapes modifiables.</p>${Object.entries(TASK_TEMPLATES).map(([id,template])=>`<button class="task-template" data-task-template="${id}"><span>${ic(template.icon)}</span><b>${template.label}</b><small>${template.tasks.length} étapes</small></button>`).join('')}</aside></div>
  <details class="feature-index"><summary>${UTILITY_FEATURES.length} outils personnels inclus</summary><p>Des outils concrets accessibles dans les tâches, le carnet, le tableau de bord et les fiches.</p><ol>${UTILITY_FEATURES.map(feature=>`<li>${esc(feature)}</li>`).join('')}</ol></details>`;
}

