function renderFarmCalendarMini(){const rows=readLocalList('astralis:gi:farm-calendar').filter(x=>!x.done).sort((a,b)=>(a.date||'').localeCompare(b.date||'')).slice(0,4);return `<section class="farm-calendar-mini"><header><div><span class="eyebrow">TON PLANNING GENSHIN</span><h3>Prochaines sessions</h3></div><button class="quiet-btn" data-nav="farming">Gérer le calendrier ${ic('arrow')}</button></header>${rows.map(row=>`<article><time>${taskDateLabel(row.date)}</time><b>${esc(row.title)}</b><span>${esc(row.category||'Session')}</span><span>${esc(row.character||'Session libre')}</span></article>`).join('')||'<p>Planifie une session dans Plan de farm pour la retrouver ici.</p>'}</section>`;}
function renderFarmPlan(){
  const weekday=new Date().getDay(),groups={1:['Liberté','Prospérité','Éphémérité','Transience','Admonition','Équité','Contention'],2:['Résistance','Diligence','Élégance','Ingéniosité','Justice','Allumage','Kindling'],3:['Ballade','Or','Lumière','Praxis','Ordre','Conflit'],4:['Liberté','Prospérité','Éphémérité','Transience','Admonition','Équité','Contention'],5:['Résistance','Diligence','Élégance','Ingéniosité','Justice','Allumage','Kindling'],6:['Ballade','Or','Lumière','Praxis','Ordre','Conflit'],0:['Tous les domaines']};
  const books=groups[weekday],day=new Date().toLocaleDateString('fr-FR',{weekday:'long'});
  if(!state.catalogs['gi:material']&&!state.loaders.has('gi:material'))loadCatalog('gi','material',{quiet:true}).then(()=>state.section==='dashboard'&&render());
  const icons={gi:ic('gi'),hsr:ic('hsr'),ww:ic('ww')};
  const giMaterials=state.catalogs['gi:material']||[];
  const giItems=books.flatMap(family=>giMaterials.filter(item=>item.typeText?.toLowerCase().includes('aptitude')&&item._name.includes(family)).sort((a,b)=>{const rank=name=>name.startsWith('Enseignement')?0:name.startsWith('Guide')?1:name.startsWith('Philosophie')?2:3;return rank(a._name)-rank(b._name)}));
  const rows=[{id:'gi',title:'Genshin Impact',items:giItems.length?giItems:books,detail:'Livres d’aptitude selon la rotation des domaines'},{id:'hsr',title:'Honkai: Star Rail',items:['Calices de matériaux de trace','Calices d’EXP & crédits'],detail:'Calices disponibles chaque jour · boss hebdomadaires selon la réinitialisation'},{id:'ww',title:'Wuthering Waves',items:['Défis de forge','Champs tacet & matériaux d’ascension'],detail:'Récompenses disponibles chaque jour · coûts en vagues chuchotantes'}];
  return `<section class="farm-plan"><div class="dashboard-section-head"><div><span class="eyebrow">ROUTES DE FARM · ${esc(day.toUpperCase())}</span><h3>À récupérer aujourd’hui</h3></div><span class="farm-date">${new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}</span></div><div class="farm-plan-grid">${rows.map(row=>`<article class="farm-game ${row.id===state.game?'active':''}"><header><span class="farm-game-icon">${icons[row.id]}</span><div><b>${row.title}</b><small>${row.detail}</small></div></header><div class="farm-items">${row.items.map((entry,index)=>{const item=typeof entry==='string'?null:entry,name=item?item._name:entry,art=item?imageSet(row.id,item,'material'):[];return `<span class="farm-item"><i class="farm-item-art game-${row.id} art-${index%3}">${art.length?img(art,'farm-item-image',name):icons[row.id]}</i>${esc(name)}</span>`}).join('')}</div>${row.id==='gi'?'<button class="quiet-btn" data-action="gi-materials">Voir les matériaux et leur disponibilité</button>':''}</article>`).join('')}</div><small class="farm-note">Les disponibilités Genshin suivent la rotation des domaines; les activités HSR et Wuwa listées ici sont quotidiennes, et les récompenses précises restent vérifiables en jeu.</small></section>`;
}
async function initializeDailyTeams(){
  const today=new Date().toLocaleDateString('sv-SE');
  await Promise.all(Object.keys(GAMES).map(async game=>{const chars=(await loadCatalog(game,'character',{quiet:true})).filter(item=>!item.preRelease),saved=Store.dailyTeam(game),owned=game==='gi'?chars.filter(item=>Store.isOwned(game,item._id)):[];if(saved?.date===today&&(!owned.length||saved.ownedOnly&&saved.ids.every(id=>Store.isOwned(game,id))))return;const source=owned.length?owned:chars;if(source.length){const team=[...source].sort(()=>Math.random()-.5).slice(0,Math.min(4,source.length));state.suppressStoreRender=true;Store.saveDailyTeam(game,{date:today,ids:team.map(item=>item._id),ownedOnly:owned.length>0});state.suppressStoreRender=false;}}));
  if(state.section==='dashboard')render();
}
