function wishCurve(plan){const scenario=plan.selectedTarget||'C0',match=scenario.match(/^C(\d+)(?:R(\d+))?$/),required=match?Number(match[1])+1:1,weaponCopies=match?Number(match[2]||0):0,weaponTarget=weaponCopies>0,budget=Math.min(360,Math.max(0,Number(plan.wishes||0)+Math.floor(Number((plan.currentPrimos??plan.primos)||0)/160))),points=[],trials=4000;let seed=885139;const rand=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/4294967296;},outcomes=[];for(let r=0;r<trials;r++){let pity=Number(plan.characterPity)||0,copies=0,guaranteed=!!plan.characterGuarantee||Number(plan.radiance)>=2,charPulls=0;while(copies<required&&charPulls<1200){charPulls++;pity++;const rate=pity<74?.006:Math.min(.006+.06*(pity-73),1);if(rand()<rate){pity=0;if(guaranteed||rand()<.55){copies++;guaranteed=false}else guaranteed=true;}}let weaponPulls=0;if(weaponTarget&&copies>=required){let wp=Number(plan.weaponPity)||0,fate=0,obtained=0;while(obtained<weaponCopies&&weaponPulls<720){weaponPulls++;wp++;if(rand()<(wp<63?.007:Math.min(.007+.07*(wp-62),1))){wp=0;if(fate>=1||rand()<.375){obtained++;fate=0}else fate++;}}if(obtained<weaponCopies)weaponPulls=721;}outcomes.push({character:copies>=required?charPulls:1201,weapon:weaponTarget&&weaponPulls>=720?721:weaponPulls,total:charPulls+weaponPulls});}const step=Math.max(1,Math.ceil(budget/24));for(let x=0;x<=budget;x+=step){const win=outcomes.filter(o=>o.total<=x).length;points.push([x,Math.round(win/trials*1000)/10]);}if(points.at(-1)?.[0]!==budget)points.push([budget,Math.round(outcomes.filter(o=>o.total<=budget).length/trials*1000)/10]);const successes=outcomes.filter(o=>o.total<=360).map(o=>o.total).sort((a,b)=>a-b);return {points,median:successes.length?successes[Math.floor(successes.length*.5)]:null,p10:successes.length?successes[Math.floor(successes.length*.1)]:null,p90:successes.length?successes[Math.floor(successes.length*.9)]:null,success:points.at(-1)?.[1]||0,budget,scenario};}
async function loadHoyolabNow(){state.hoyolabBusy=true;try{const response=await fetch('/api/hoyolab/resin?refresh=1',{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'Lecture Battle Chronicle impossible');state.hoyolabResin=data;state.hoyolabStatus={...(state.hoyolabStatus||{}),connected:true};return true;}catch(error){state.hoyolabResin={error:error.message};return false;}finally{state.hoyolabBusy=false;}}
function loadHoyolabStatus(){if(state.hoyolabBusy)return;state.hoyolabBusy=true;fetch('/api/hoyolab/status',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()).then(async status=>{state.hoyolabStatus=status;if(status.connected){const response=await fetch('/api/hoyolab/resin',{cache:'no-store'});const data=await response.json();state.hoyolabResin=response.ok?data:{error:data.error||'Résine non disponible'};}else state.hoyolabResin=null;}).catch(error=>{state.hoyolabStatus={connected:false,error:error.message||'Serveur local à relancer'};}).finally(()=>{state.hoyolabBusy=false;if(['hoyolab','dashboard'].includes(state.section))renderPageOnly();});}
function renderHoyolabResinCard(){if(!state.hoyolabStatus&&!state.hoyolabBusy)loadHoyolabStatus();const resin=state.hoyolabResin,status=state.hoyolabStatus;if(!status?.connected)return `<section class="hoyolab-resin-card" data-dashboard-widget="resin"><div><span class="eyebrow">HOYOLAB · RÉSINE</span><h3>Relie Battle Chronicle</h3><p>La résine s’affichera ici après une connexion HoYoLAB configurée sur cet appareil.</p></div><button class="quiet-btn" data-nav="hoyolab">Configurer ${ic('arrow')}</button></section>`;if(!resin||resin.error)return `<section class="hoyolab-resin-card" data-dashboard-widget="resin"><div><span class="eyebrow">HOYOLAB · RÉSINE</span><h3>Connexion à actualiser</h3><p>${esc(resin?.error||'Récupération de Battle Chronicle…')}</p></div><button class="quiet-btn" data-action="hoyolab-refresh">Réessayer</button></section>`;const recovery=Math.max(0,Number(resin.recoverySeconds)||0);return `<section class="hoyolab-resin-card connected" data-dashboard-widget="resin"><div class="resin-gauge"><img src="https://gi.yatta.moe/assets/UI/UI_ItemIcon_201.png" alt="" loading="lazy"><b data-resin-value="${resin.current}" data-resin-max="${resin.maximum}" data-resin-updated="${resin.updatedAt}" data-resin-recovery="${recovery}">${resin.current}</b><small>/ ${resin.maximum}</small></div><div class="resin-copy"><span class="eyebrow">BATTLE CHRONICLE · UID ${esc(status.uid)}</span><h3>Résine originale</h3><p>Prochain point estimé dans <b data-resin-next data-resin-updated="${resin.updatedAt}" data-resin-current="${resin.current}" data-resin-max="${resin.maximum}" data-resin-recovery="${recovery}">—</b> · actualisé ${new Date(resin.updatedAt*1000).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</p><small>Régénération calculée à 1 résine / 8 min, plafonnée à ${resin.maximum}.</small></div><button class="quiet-btn" data-action="hoyolab-refresh">Actualiser</button></section>`;}
function renderHoyolabPage(){if(!state.hoyolabStatus&&!state.hoyolabBusy)loadHoyolabStatus();const connected=!!state.hoyolabStatus?.connected,resin=state.hoyolabResin;return `<section class="hoyolab-hub"><header class="hoyolab-hero"><div><span class="eyebrow">OUTILS OFFICIELS · CONNEXION LOCALE</span><h2>HoYoLAB, dans Astralis</h2><p>Résine Battle Chronicle, outils de compte et raccourcis Genshin. La connexion est enregistrée chiffrée par Windows pour ton compte utilisateur seulement.</p></div><span class="hoyolab-lock">${ic('shield')} DPAPI · local</span></header>${renderHoyolabResinCard()}<section class="hoyolab-connect surface-card"><header><div><span class="eyebrow">${connected?'SESSION ENREGISTRÉE':'CONNEXION BATTLE CHRONICLE'}</span><h3>${connected?`Compte · UID ${esc(state.hoyolabStatus.uid)}`:'Relier mon compte Genshin'}</h3><p>Utilise seulement ton UID et les cookies de session HoYoLAB. Astralis ne demande jamais ton mot de passe. Le cookie est envoyé au serveur local, chiffré avec DPAPI dans AppData, et exclu des fichiers d’export.</p></div><span class="hoyolab-status ${connected?'ok':''}">${connected?'Connecté sur cet appareil':'Non connecté'}</span></header><div class="hoyolab-form"><label>UID Genshin<input id="hoyolab-uid" inputmode="numeric" maxlength="12" value="${esc(state.hoyolabStatus?.uid||'')}" placeholder="Ex. 800000000"></label><label>Serveur<select id="hoyolab-region"><option value="os_euro">Europe</option><option value="os_usa">Amérique</option><option value="os_asia">Asie</option><option value="os_cht">TW / HK / MO</option></select></label><label class="hoyolab-cookie-field">Cookie HoYoLAB (format : valeur uniquement, sans « nom= »)<input id="hoyolab-ltuid" type="password" autocomplete="off" placeholder="ltuid_v2 · valeur uniquement"><input id="hoyolab-ltoken" type="password" autocomplete="off" placeholder="ltoken_v2 · valeur uniquement"><input id="hoyolab-ltoken2" type="password" autocomplete="off" placeholder="ltoken · valeur uniquement"><small>Renseigne ltuid_v2 et ltoken_v2 avec leurs valeurs. Si ton navigateur fournit aussi ltoken, ajoute-le dans le troisième champ. Copie chaque valeur depuis hoyolab.com, sans le nom ni le point-virgule. Ne saisis jamais ton mot de passe.</small></label><div class="hoyolab-actions"><button class="button-primary" data-action="hoyolab-save">${connected?'Mettre à jour la connexion':'Enregistrer et tester'}</button><button class="quiet-btn" data-action="hoyolab-refresh">Actualiser la résine</button>${connected?'<button class="quiet-btn danger" data-action="hoyolab-disconnect">Effacer du coffre local</button>':''}</div><small>Pour obtenir le cookie, utilise les outils de développement de ton navigateur sur HoYoLAB. Ne l’envoie jamais à quelqu’un et ne l’ajoute pas à un export Astralis.</small></div>${resin?.error?`<p class="hoyolab-error">${esc(resin.error)}</p>`:''}</section><section class="hoyolab-tools"><header><span class="eyebrow">OUTILS HOYOLAB · INTÉGRÉS</span><h3>Ouvrir dans Astralis</h3><p>Les outils s’affichent dans ce panneau. Certains services HoYoLAB peuvent limiter leur intégration selon la session du navigateur.</p></header><nav class="hoyolab-tool-tabs" aria-label="Outils HoYoLAB"><button type="button" data-hoyolab-tool="chronicle" class="${state.hoyolabTool==='chronicle'?'active':''}">Battle Chronicle</button><button type="button" data-hoyolab-tool="checkin" class="${state.hoyolabTool==='checkin'?'active':''}">Check-in</button><button type="button" data-hoyolab-tool="map" class="${state.hoyolabTool==='map'?'active':''}">Carte interactive</button><button type="button" data-hoyolab-tool="community" class="${state.hoyolabTool==='community'?'active':''}">Communauté</button></nav><div class="hoyolab-embed-wrap"><iframe class="hoyolab-embed" src="${({chronicle:'https://act.hoyolab.com/app/community-game-records-sea/index.html?gid=2',checkin:'https://act.hoyolab.com/ys/event/signin-sea-v3/index.html',map:'https://act.hoyolab.com/ys/app/interactive-map/index.html',community:'https://www.hoyolab.com/home'})[state.hoyolabTool]||'https://act.hoyolab.com/app/community-game-records-sea/index.html?gid=2'}" title="Outil HoYoLAB intégré à Astralis" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="clipboard-read; clipboard-write; fullscreen"></iframe></div><small class="hoyolab-embed-help">Si une page reste blanche, HoYoLAB refuse son affichage intégré pour cette session. Le reste de la page Astralis reste accessible.</small></section></section>`;}

function renderWishTracker(){for(const category of ['character','weapon'])if(!state.catalogs[`gi:${category}`]&&!state.loaders.has(`gi:${category}`))loadCatalog('gi',category,{quiet:true}).then(()=>state.section==='wishes'&&renderPageOnly());const p=wishPlan();if(!(Number(p.currentPrimos)||0)&&Number(p.primos)>0&&!p.currentPrimosExplicit){p.currentPrimos=Number(p.primos);localStorage.setItem(GI_WISH_KEY,JSON.stringify(p));}const curve=wishCurve(p),chance=curve.success,days=Math.max(0,Math.ceil((new Date(`${p.patchEnd||'2026-12-16'}T23:59:59`)-new Date())/86400000)),recent=p.history.slice(-14);let running=0;const values=recent.map(row=>running+=Math.max(0,Number(row.primos)||0)+Math.max(0,Number(row.count)||0)*160),peak=Math.max(1,...values),chartPoints=values.map((value,i)=>`${48+i*(652/Math.max(1,values.length-1))},${166-(value/peak)*126}`).join(' ');return `<section class="wish-hub"><header class="wish-hero"><div><span class="eyebrow">PLANIFICATEUR DE VŒUX · GENSHIN</span><h2>Objectif, pity et budget</h2><p>Suivi enregistré sur cet appareil. Les chances sont une estimation Monte-Carlo selon les règles publiques et une approximation communautaire de la pity progressive; elles ne garantissent aucun résultat.</p></div><div class="wish-probability"><strong>${chance}%</strong><span>chance estimée d’atteindre l’objectif avec le budget actuel</span></div></header><section class="wish-target-analysis"><div><span class="eyebrow">PROBABILITÉS CUMULÉES · BUDGET ACTUEL</span><h3>Scénarios de possession</h3><p>Simulation stable à graine fixe; les pourcentages restent identiques tant que les données ne changent pas.</p></div><div class="wish-chart-panel"><label class="wish-scenario-select">Objectif analysé<select data-wish-scenario>${Array.from({length:7},(_,c)=>`<option value="C${c}" ${p.selectedTarget===`C${c}`?'selected':''}>C${c}R0 · ${c+1} copie${c?'s':''}</option>`).join('')}${Array.from({length:7},(_,c)=>Array.from({length:5},(_,r)=>`<option value="C${c}R${r+1}" ${p.selectedTarget===`C${c}R${r+1}`?'selected':''}>C${c}R${r+1} · constellation + arme</option>`).join('')).join('')}</select></label><div class="wish-curve" role="img" aria-label="Courbe de probabilité cumulée selon le nombre de vœux"><svg viewBox="0 0 720 230" preserveAspectRatio="none"><line x1="48" y1="20" x2="48" y2="190"/><line x1="48" y1="190" x2="700" y2="190"/><line class="gridline" x1="48" y1="105" x2="700" y2="105"/><text x="8" y="24">100%</text><text x="22" y="109">50%</text><text x="32" y="194">0%</text><polyline points="${curve.points.map(([x,y])=>`${48+x/Math.max(1,curve.budget)*652},${190-y*1.7}`).join(' ')}"/><text x="48" y="220">0 vœu</text><text x="620" y="220">${curve.budget} vœux</text></svg></div><div class="wish-stat-row"><span><b>${curve.success}%</b> chance au budget actuel</span><span><b>${curve.median??'—'}</b> vœux · médiane parmi les réussites</span><span><b>${curve.p10??'—'}–${curve.p90??'—'}</b> vœux · intervalle P10–P90</span></div><small class="wish-model-note">Courbe Monte-Carlo reproductible · 4 000 essais · soft pity approximée après 73 vœux (perso) / 62 (arme). L’algorithme exact de Capturing Radiance n’est pas public.</small></div></section><div class="wish-form-grid"><label>Personnage visé<input type="text" maxlength="40" data-wish-field="targetName" value="${esc(p.targetName||'')}" placeholder="Ex. Mitya, Vesna"></label><label>Vœux disponibles<input type="number" min="0" data-wish-field="wishes" value="${p.wishes}"></label><label>Vœux prévus pour la bannière d’arme<input type="number" min="0" data-wish-field="weaponWishes" value="${p.weaponWishes||0}"><small>Le reste du budget est simulé sur la bannière personnage.</small></label><label>Pity personnage<input type="number" min="0" max="89" data-wish-field="characterPity" value="${p.characterPity}"></label><label>50/50 perdus consécutifs<input type="number" min="0" max="2" data-wish-field="radiance" value="${p.radiance}"></label><label>Pity arme<input type="number" min="0" max="79" data-wish-field="weaponPity" value="${p.weaponPity}"></label><label>Constellations visées<input type="number" min="0" max="6" data-wish-field="targetCopies" value="${Math.max(0,p.targetCopies-1)}"><small>Copies totales nécessaires : C${Math.max(0,p.targetCopies-1)}</small></label><label class="wish-check"><input type="checkbox" data-wish-field="characterGuarantee" ${p.characterGuarantee?'checked':''}> Prochain personnage vedette garanti</label><label class="wish-check"><input type="checkbox" data-wish-field="targetWeapon" ${p.targetWeapon?'checked':''}> Ajouter l’arme signature R1 à l’objectif</label><label class="wish-check"><input type="checkbox" data-wish-field="weaponGuarantee" ${p.weaponGuarantee?'checked':''}> Prochaine arme 5★ garantie sur la bannière</label></div><section class="wish-current-account"><div><span class="eyebrow">MON COMPTE GENSHIN</span><h3>Primos et vœux disponibles</h3><p>Solde saisi par toi, conservé sur cet appareil.</p></div><label>Primos actuelles<input type="number" min="0" data-wish-field="currentPrimos" value="${Number(p.currentPrimos||p.primos)||0}"></label><b>${Math.floor((Number(p.currentPrimos||p.primos)||0)/160)} vœux</b></section>${renderWishForecast(p)}${renderWishPeriodSummary(p)}${renderWishPullHistory(p)}<section class="wish-daily"><div><span class="eyebrow">ÉPARGNE QUOTIDIENNE</span><h3>Ajouter les gains du jour</h3><p>Chaque entrée s’ajoute à ton total et reste modifiable dans l’historique.</p></div><label>Primos gagnés<input id="wish-daily-primos" type="number" min="0" placeholder="Ex. 60"></label><label>Vœux gagnés<input id="wish-daily-pulls" type="number" min="0" placeholder="Ex. 1"></label><button class="button-primary" data-action="wish-log">Ajouter aujourd’hui</button></section><section class="wish-chart"><header><div><span class="eyebrow">HISTORIQUE · 14 DERNIERS JOURS</span><h3>Progression de l’épargne</h3></div><span>${p.primos.toLocaleString('fr-FR')} primos · ${p.wishes} vœux</span></header><div class="wish-bars" role="img" aria-label="Progression cumulée des primogemmes sur quatorze jours">${renderSavingsChart(recent,values,peak)}</div></section><p class="farm-disclaimer">HoYoverse indique 0,6 % de taux de base et 55 % de probabilité consolidée du personnage vedette (« Capturing Radiance »). Le mécanisme interne exact et les taux progressifs par vœu ne sont pas publiés : le pourcentage ci-dessus sert à comparer des budgets, pas à prévoir un résultat individuel. <a href="https://genshin.hoyoverse.com/en/news/detail/125274" target="_blank" rel="noreferrer">Règles officielles des vœux</a></p></section>`;}
function renderCalcSheets(){
 for(const category of ['character','weapon','artifact'])if(!state.catalogs[`gi:${category}`])loadCatalog('gi',category,{quiet:true}).then(()=>renderPageOnly());
  const teams=Store.teams('gi'),sheets=readLocalList(calcKey),chars=state.catalogs['gi:character']||[],weapons=state.catalogs['gi:weapon']||[],artifacts=state.catalogs['gi:artifact']||[],derive=(dpr,dps,time)=>{dpr=Number(dpr)||0;dps=Number(dps)||0;time=Number(time)||0;if(!dps&&dpr&&time)dps=dpr/time;if(!dpr&&dps&&time)dpr=dps*time;return {dpr,dps,time};};const rows=teams.map(t=>({id:t.id,name:t.name,...derive(t.dpr,t.dps,t.time),weapon:t.members?.map(s=>itemById('gi','weapon',s.weapon)?._name).filter(Boolean).join(', ')||'—',set:t.members?.map(s=>itemById('gi','artifact',s.set)?._name).filter(Boolean).join(', ')||'—',rotation:t.rotationNotes||t.rotation?.map(a=>`${a.character} ${a.code||''}`).join(' → ')||'—'}));for(const sheet of sheets){const values=derive(sheet.dpr,sheet.dps,sheet.time),row={id:sheet.teamId||sheet.id,name:sheet.title,...values,weapon:(sheet.members||[]).map(m=>m.weapon).filter(Boolean).join(', ')||'—',set:(sheet.members||[]).map(m=>m.set).filter(Boolean).join(', ')||'—',rotation:sheet.rotation||'—'};const at=sheet.teamId?rows.findIndex(item=>item.id===sheet.teamId):-1;if(at>=0)rows[at]={...rows[at],...row,dpr:values.dpr||rows[at].dpr,dps:values.dps||rows[at].dps,time:values.time||rows[at].time};else rows.push(row);}
 const topDpr=Math.max(0,...rows.map(r=>r.dpr)),positive=rows.map(r=>r.dpr).filter(Boolean),lastDpr=positive.length?Math.min(...positive):0,sortKey=state.calcSort||'dpr',direction=state.calcSortDirection||-1,sorted=[...rows].sort((a,b)=>{const av=sortKey==='share'?(topDpr?a.dpr/topDpr:0):a[sortKey]??'',bv=sortKey==='share'?(topDpr?b.dpr/topDpr:0):b[sortKey]??'';return (typeof av==='number'&&typeof bv==='number'?(av-bv):String(av).localeCompare(String(bv),'fr',{numeric:true}))*direction;});
 return `<datalist id="calc-characters">${chars.map(x=>`<option value="${esc(x._name)}"></option>`).join('')}</datalist><datalist id="calc-weapons">${weapons.map(x=>`<option value="${esc(x._name)}"></option>`).join('')}</datalist><datalist id="calc-artifacts">${artifacts.map(x=>`<option value="${esc(x._name)}"></option>`).join('')}</datalist><section class="calc-intro"><div><span class="eyebrow">ANALYSE DE COMPOSITIONS · GENSHIN</span><h2>Calc Sheets</h2><p>Une feuille fixe par équipe, calquée sur ton comparatif : quatre personnages, équipement, rotation, DPR et DPS. Les cases se remplissent directement.</p></div><button class="button-primary" data-action="calc-new">＋ Créer une feuille</button></section><section class="calc-summary"><article><small>ÉQUIPES COMPARÉES</small><b>${rows.length}</b></article><article><small>MEILLEUR DPR SAISI</small><b>${topDpr?topDpr.toLocaleString('fr-FR'):'—'}</b></article><article><small>ÉCART PREMIÈRE / DERNIÈRE</small><b>${topDpr&&lastDpr?`${Math.round((topDpr-lastDpr)/topDpr*100)} %`:'—'}</b></article><article><small>TEMPS MOYEN SAISI</small><b>${rows.length?`${(rows.reduce((x,r)=>x+r.time,0)/rows.length).toFixed(1)} s`:'—'}</b></article></section><section class="calc-panel"><header><div><span class="eyebrow">TABLEAU RÉCAPITULATIF AUTOMATIQUE</span><h3>Résultats des équipes</h3></div><label>Filtrer <input id="calc-filter" placeholder="Nom d’équipe / rotation"></label></header><div class="calc-table-wrap"><table class="calc-table"><thead><tr><th><button type="button" data-calc-sort="name">Équipe ↕</button></th><th><button type="button" data-calc-sort="dpr">DPR ↕</button></th><th><button type="button" data-calc-sort="dps">DPS ↕</button></th><th><button type="button" data-calc-sort="share">% du meilleur ↕</button></th><th><button type="button" data-calc-sort="time">Temps ↕</button></th><th><button type="button" data-calc-sort="rotation">Rotation ↕</button></th></tr></thead><tbody>${sorted.map(row=>`<tr><td>${esc(row.name)}</td><td>${row.dpr?row.dpr.toLocaleString('fr-FR'):'—'}</td><td>${row.dps?row.dps.toLocaleString('fr-FR'):'—'}</td><td>${topDpr&&row.dpr?`${(row.dpr/topDpr*100).toFixed(1)} %`:'—'}</td><td>${row.time||'—'}</td><td>${esc(row.rotation)}</td></tr>`).join('')||'<tr><td colspan="6">Ajoute tes résultats dans une feuille pour les comparer ici.</td></tr>'}</tbody></table></div></section><section class="calc-sheets-grid">${sheets.map((sheet,i)=>`<article class="calc-sheet fixed-sheet" style="--sheet-accent:${esc(sheet.color||'#c7a9ff')};--sheet-size:${Number(sheet.size)||13}px"><header><input data-sheet="${i}" data-sheet-field="title" value="${esc(sheet.title)}" aria-label="Nom du tableau"><button data-sheet-delete="${i}" title="Supprimer">×</button></header><div class="calc-table-wrap"><table class="team-calc-table"><thead><tr><th><input data-sheet="${i}" data-sheet-field="title" value="${esc(sheet.title)}"></th><th>DPS perso</th><th>% of the team</th><th>Weapon</th><th>Set</th></tr></thead><tbody>${Array.from({length:4},(_,j)=>{const r=sheet.members?.[j]||{};return `<tr><td><label class="calc-entity-cell">${(()=>{const x=chars.find(v=>v._name===r.name);return x?img([splashImage('gi',x),...imageSet('gi',x,'character')],'',x._name):''})()}<input list="calc-characters" data-sheet="${i}" data-sheet-member="${j}" data-member-field="name" value="${esc(r.name||'')}" placeholder="Personnage…" aria-label="Personnage ${j+1}"></label></td><td><input type="number" data-sheet="${i}" data-sheet-member="${j}" data-member-field="dps" value="${esc(r.dps||'')}"></td><td><input data-sheet="${i}" data-sheet-member="${j}" data-member-field="share" value="${esc(r.share||'')}"></td><td><label class="calc-entity-cell">${(()=>{const x=weapons.find(v=>v._name===r.weapon);return x?img(imageSet('gi',x,'weapon'),'',x._name):''})()}<input list="calc-weapons" data-sheet="${i}" data-sheet-member="${j}" data-member-field="weapon" value="${esc(r.weapon||'')}" placeholder="Arme…" aria-label="Arme ${j+1}"></label></td><td><label class="calc-entity-cell">${(()=>{const x=artifacts.find(v=>v._name===r.set);return x?img(imageSet('gi',x,'artifact'),'',x._name):''})()}<input list="calc-artifacts" data-sheet="${i}" data-sheet-member="${j}" data-member-field="set" value="${esc(r.set||'')}" placeholder="Set…" aria-label="Set ${j+1}"></label></td></tr>`}).join('')}<tr class="team-calc-rotation"><th colspan="2">Rotation · temps <input data-sheet="${i}" data-sheet-field="time" value="${esc(sheet.time||'')}" aria-label="Temps en secondes"> s</th><td colspan="3"><input data-sheet="${i}" data-sheet-field="rotation" value="${esc(sheet.rotation||'')}" placeholder="Rotation complète"></td></tr><tr class="team-calc-total"><th>DPR <input data-sheet="${i}" data-sheet-field="dpr" value="${esc(sheet.dpr||'')}"></th><th colspan="2">DPS <input data-sheet="${i}" data-sheet-field="dps" value="${esc(sheet.dps||'')}"></th><td colspan="2"><span data-sheet-share="${i}">Parts calculées automatiquement</span></td></tr></tbody></table></div><textarea data-sheet="${i}" data-sheet-field="notes" placeholder="Notes, hypothèses et conditions de calcul">${esc(sheet.notes||'')}</textarea><div class="calc-sheet-tools"><label>Couleur <input type="color" data-sheet="${i}" data-sheet-field="color" value="${esc(sheet.color||'#c7a9ff')}"></label><label>Taille <input type="range" min="11" max="18" data-sheet="${i}" data-sheet-field="size" value="${Number(sheet.size)||13}"></label><label>Photo <input type="file" accept="image/*" data-sheet-photo="${i}"></label><button data-sheet-export="${i}">Exporter CSV</button></div>${sheet.photo?`<img class="calc-sheet-photo" src="${sheet.photo}" alt="Image de référence">`:''}</article>`).join('')}</section>`;
}
function giArtifactPieceImage(set,index){if(!set)return [];const key=['flower','plume','sands','goblet','circlet'][index],images=set.images||{},file=images[`filename_${key}`];return [...new Set([images[`mihoyo_${key}`],file?`https://enka.network/ui/${encodeURIComponent(file)}.png`:'',file?`https://gi.yatta.moe/assets/UI/${encodeURIComponent(file)}.png`:'',file?`https://api.ambr.top/assets/UI/reliquary/${encodeURIComponent(file)}.png`:'',imageSet('gi',set,'artifact')[0]].filter(Boolean))];}
