function newsSourceFrame(url,title){try{const parsed=new URL(url);if(parsed.protocol!=='https:')return '';return `<div class="news-source-embed"><b>Source originale</b><p>Le texte fourni par le flux est affiché ci-dessus. Les pages tierces bloquent souvent leur affichage intégré.</p><a href="${esc(parsed.href)}" target="_blank" rel="noopener noreferrer">Lire la source : ${esc(title||parsed.hostname)} ↗</a></div>`;}catch{return '';}}
function youtubeVideoId(value){const raw=String(value||'').trim();if(/^[\w-]{11}$/.test(raw))return raw;try{const url=new URL(raw);if(url.hostname.endsWith('youtu.be'))return url.pathname.split('/').filter(Boolean)[0]||'';const id=url.searchParams.get('v');if(id)return id;const match=url.pathname.match(/\/(?:embed|shorts|live)\/([\w-]{11})/);return match?.[1]||'';}catch{return '';}}
function youtubeEmbed(video){const id=youtubeVideoId(video?.id||video?.embed||video?.link||video?.url);return id?`https://www.youtube-nocookie.com/embed/${id}?rel=0&playsinline=1` :'';}
function youtubeWatch(video){const id=youtubeVideoId(video?.id||video?.link||video?.url||video?.embed);return id?`https://youtu.be/${id}`:(video?.link||video?.url||'https://www.youtube.com/@GenshinImpact');}
function relatedOfficialVideo(title,videos,articleIds=[]){const ids=Array.isArray(articleIds)?articleIds:[articleIds];const id=ids.map(youtubeVideoId).find(Boolean);if(id)return {id,title,embed:youtubeEmbed({id}),link:youtubeWatch({id})};const words=String(title||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/[^a-z0-9]+/).filter(x=>x.length>3);const match=(videos||[]).map(v=>({v,score:words.filter(word=>String(v.title||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(word)).length})).sort((a,b)=>b.score-a.score).find(x=>x.score>=2)?.v;if(!match)return null;const normalized={...match,id:youtubeVideoId(match.id||match.link||match.embed),embed:youtubeEmbed(match),link:youtubeWatch(match)};return normalized.id?normalized:null;}
