function renderDashboard(){
  ensureDashboardDemoChangelog();
  if(!state.catalogs[`${state.game}:character`]&&!state.loaders.has(`${state.game}:character`))loadCatalog(state.game,'character',{quiet:true}).then(()=>render());
  const favoriteMap=Store.favorites(),favoriteKeys=Object.keys(favoriteMap).filter(key=>key.startsWith(`${state.game}:`)),favoriteCategories=[...new Set(favoriteKeys.map(key=>key.split(':')[1]).filter(category=>['character','weapon','artifact'].includes(category)))];
  if(favoriteCategories.some(category=>!state.catalogs[`${state.game}:${category}`])){Promise.all(favoriteCategories.filter(category=>!state.catalogs[`${state.game}:${category}`]).map(category=>loadCatalog(state.game,category,{quiet:true}))).then(render);return '<div class="loading-panel"><span class="loader"></span><b>Préparation de ton tableau de bord</b><p>Chargement des favoris et de tes données personnelles.</p></div>';}
  const favorites=[];for(const category of favoriteCategories)for(const item of state.catalogs[`${state.game}:${category}`]||[])if(Store.isFavorite(state.game,category,item._id))favorites.push(item);
  const teams=Store.teams(state.game),notes=Store.notes(state.game),tasks=Store.tasks(state.game),openTasks=tasks.filter(task=>!task.done),tipList=Array.isArray(DASH_TIPS[state.game])&&DASH_TIPS[state.game].length?DASH_TIPS[state.game]:DASH_TIPS.gi,tip=tipList[new Date().getDate()%tipList.length],chars=state.catalogs[`${state.game}:character`]||[],now=new Date(),dateLabel=now.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});
  let daily=Store.dailyTeam(state.game);const today=now.toLocaleDateString('sv-SE');if(chars.length&&(!daily||daily.date!==today)){const available=chars.filter(item=>!item.preRelease),owned=available.filter(item=>Store.isOwned(state.game,item._id)),pool=[...(owned.length?owned:available)].sort(()=>Math.random()-.5).slice(0,Math.min(4,owned.length||available.length));daily={date:today,ids:pool.map(x=>x._id),ownedOnly:owned.length>0};Store.saveDailyTeam(state.game,daily);}
  const ownedMap=Store.ownedMap(state.game),dailyCards=(daily?.ids||[]).map(id=>chars.find(x=>x._id===id)).filter(Boolean).filter(item=>!ownedMap||!daily?.ownedOnly||Store.isOwned(state.game,item._id));
  const allCounts=Object.fromEntries(Object.keys(GAMES).map(game=>[game,state.catalogs[`${game}:character`]?.length]));for(const game of Object.keys(GAMES))if(allCounts[game]===undefined&&!state.loaders.has(`${game}:character`))loadCatalog(game,'character',{quiet:true}).then(()=>state.section==='dashboard'&&render());
  const dueTasks=openTasks.filter(task=>task.due).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3),shortDate=task=>task.due?taskDateLabel(task.due):'Sans échéance';
  return `<div class="dashboard-experience dashboard-command-centre">
    ${renderDashboardWelcome()}${renderDashboardChangeStrip()}
    <header class="dashboard-command-hero" data-dashboard-widget="welcome"><div class="dashboard-hero-copy"><span class="dashboard-kicker">${esc(prefs.appName||'ASTRALIS')} <i></i> CENTRE DE CONTRÔLE</span><p class="dashboard-date">${esc(dateLabel)}</p><h1>Bonjour${travelerProfile().name?`, ${esc(travelerProfile().name)}`:''}.</h1><p class="dashboard-hero-subtitle">Tout ce qui compte pour ta prochaine session, réuni au même endroit.</p><div class="dashboard-hero-actions"><button class="button-primary" data-nav="farming">${ic('layers')}<span>Préparer ma session</span></button><button class="quiet-btn" data-action="new-note">${ic('plus')} Note rapide</button></div></div><div class="dashboard-hero-status"><span class="dashboard-orbit orbit-one"></span><span class="dashboard-orbit orbit-two"></span><span class="dashboard-orbit-core">${GAMES[state.game].icon}</span><small>UNIVERS ACTIF</small><b>${esc(GAMES[state.game].short)}</b><button data-nav="customize">Personnaliser l’accueil ${ic('arrow')}</button></div></header>
    <nav class="dashboard-universe-switch" aria-label="Choisir un univers">${Object.entries(GAMES).map(([game,g])=>`<button class="${state.game===game?'active':''}" style="--game-accent:${g.accent}" data-game="${game}"><span>${g.icon}</span><b>${g.label}</b><small>${allCounts[game]===undefined?'Synchronisation…':`${allCounts[game]} personnages`}</small><i>${state.game===game?'ACTIF':'OUVRIR'}</i></button>`).join('')}</nav>
    <section class="dashboard-quick-stats" data-dashboard-widget="metrics" aria-label="Résumé personnel"><article><span class="stat-mark">${ic('heart')}</span><small>FAVORIS</small><b>${favorites.length}</b><button data-nav="favorites">Parcourir ${ic('arrow')}</button></article><article><span class="stat-mark">${ic('users')}</span><small>ÉQUIPES</small><b>${teams.length}</b><button data-nav="teams">Ouvrir l’atelier ${ic('arrow')}</button></article><article><span class="stat-mark">${ic('tasks')}</span><small>À TERMINER</small><b>${openTasks.length}</b><button data-nav="tasks">Voir les tâches ${ic('arrow')}</button></article><article><span class="stat-mark">${ic('notebook')}</span><small>NOTES</small><b>${notes.length}</b><button data-nav="notes">Ouvrir le carnet ${ic('arrow')}</button></article></section>
    ${state.game==='gi'?`<section class="dashboard-feature-zone"><div class="dashboard-feature-title"><div><span class="dashboard-kicker">À SURVEILLER</span><h2>Le prochain rendez-vous</h2></div><button class="dashboard-text-link" data-nav="endgame">Tous les endgames ${ic('arrow')}</button></div><div class="dashboard-feature-grid">${renderGiDashboardPlanning(chars)}<aside class="dashboard-side-stack">${renderHoyolabResinCard()}${renderWishMini()}</aside></div></section>`:`<section class="dashboard-feature-zone"><div class="dashboard-feature-title"><div><span class="dashboard-kicker">À SURVEILLER</span><h2>Reprends là où tu en étais</h2></div></div><div class="dashboard-non-gi-focus"><article><span class="dashboard-kicker">TES ÉQUIPES</span><b>${teams.length} équipe(s) enregistrée(s)</b><button data-nav="teams">Ouvrir l’atelier ${ic('arrow')}</button></article><article><span class="dashboard-kicker">TES OBJECTIFS</span><b>${openTasks.length} tâche(s) à terminer</b><button data-nav="tasks">Voir mes objectifs ${ic('arrow')}</button></article></div></section>`}
    <section class="dashboard-daily-team ${state.dailySpinning?'spinning':''}" data-dashboard-widget="daily-team"><div class="daily-team-copy"><span class="dashboard-kicker">SUGGESTION DU JOUR · ${esc(dateLabel)}</span><h2>Une équipe, juste pour aujourd’hui</h2><p>${daily?.ownedOnly?'Le tirage utilise uniquement les personnages que tu possèdes.':'Aucun personnage marqué comme possédé : toute la collection peut être tirée.'}</p><button class="button-primary" data-action="daily-spin">${ic('shuffle')}<span>Relancer la sélection</span></button><div class="daily-team-names">${dailyCards.map(c=>`<button data-detail="${esc(c._id)}" data-item-category="character">${esc(c._name)}</button>`).join('')}</div></div><div class="daily-team-portraits">${dailyCards.map((c,i)=>`<button class="daily-wheel-avatar" style="--i:${i}" data-detail="${esc(c._id)}" data-item-category="character" title="${esc(c._name)}">${img(avatarImage(state.game,c),'',c._name)}</button>`).join('')||'<span class="dashboard-empty-slot">La sélection arrive avec la base de personnages.</span>'}</div></section>
    <section class="dashboard-workbench"><div class="dashboard-feature-title"><div><span class="dashboard-kicker">TA SESSION</span><h2>À faire et à préparer</h2></div><button class="dashboard-text-link" data-nav="farming">Ouvrir le plan de farm ${ic('arrow')}</button></div><div class="dashboard-workbench-grid">${state.game==='gi'?renderGenshinChecklist():''}${renderAssistantMini()}${state.game==='gi'?renderFarmCalendarMini():''}${state.game==='gi'?renderGiEventsMini():''}<article class="dashboard-agenda" data-dashboard-widget="next"><header><div><span class="dashboard-kicker">TES ÉCHÉANCES</span><h3>Prochaines tâches</h3></div><button class="dashboard-text-link" data-nav="tasks">Tout voir ${ic('arrow')}</button></header>${dueTasks.length?dueTasks.map(task=>`<div class="dashboard-agenda-row"><time>${esc(shortDate(task))}</time><span><b>${esc(task.title)}</b><small>${esc(task.category||'Objectif')}</small></span><i>›</i></div>`).join(''):'<p class="dashboard-quiet-empty">Aucune échéance enregistrée. Ajoute une tâche quand tu veux planifier la suite.</p>'}</article><article class="dashboard-tip-card"><span class="dashboard-kicker">REPÈRE DU JOUR</span><div class="dashboard-tip-symbol">${ic('bulb')}</div><h3>Avance sur une priorité à la fois.</h3><p>${esc(tip)}</p><small>${esc(GAMES[state.game].label)} · conseil du jour</small></article></div></section>
    ${state.game==='gi'?`${renderGiFarmDashboardCards()}${renderDashboardEnkaBuild()}${renderGenshinBirthdays(chars)}<section class="dashboard-profile" data-dashboard-widget="profile"><div><span class="dashboard-kicker">VITRINE ENKA</span><h3>${state.giProfile?.playerInfo?.nickname?`Bonjour ${esc(state.giProfile.playerInfo.nickname)}`:'Tes builds publics, à portée de main'}</h3><p>${state.giProfile?.avatarInfoList?.length?`${state.giProfile.avatarInfoList.length} personnages visibles dans ta vitrine.`:'Relie ton UID pour afficher tes personnages exposés et leurs builds.'}</p></div><button class="quiet-btn" data-nav="profile">${state.giProfile?'Voir mon profil':'Configurer Enka'} ${ic('arrow')}</button></section>`:''}
    <section class="dashboard-favorites-zone dashboard-section" data-dashboard-widget="favorites"><header class="dashboard-feature-title"><div><span class="dashboard-kicker">ACCÈS RAPIDE</span><h2>Ta sélection</h2></div><button class="dashboard-text-link" data-nav="favorites">Tous les favoris ${ic('arrow')}</button></header><div class="dashboard-favorites">${favorites.length?favorites.slice(0,4).map(item=>renderCatalogCard(item)).join(''):'<div class="dashboard-empty"><b>Ta collection commence ici.</b><p>Ajoute des personnages, armes ou sets en favoris pour les retrouver ici.</p><button class="quiet-btn" data-nav="characters">Explorer la collection</button></div>'}</div></section>
    <footer class="dashboard-command-footer"><span>Ton espace est enregistré sur cet appareil.</span><button class="dashboard-text-link" data-action="dashboard-reset-layout">Réinitialiser l’accueil</button>${renderDashboardControls()}<button class="quiet-btn" data-nav="customize">Tous les réglages ${ic('arrow')}</button></footer>
  </div>`;
}

function ensureDashboardDemoChangelog(){const key=`astralis:${state.game}:data-journal`;let rows=[];try{rows=JSON.parse(localStorage.getItem(key)||'[]')}catch{}if(rows.some(row=>row.demo))return;rows.unshift({id:`demo-astralis-2026-11-${state.game}`,demo:true,at:new Date().toISOString(),game:`${GAMES[state.game].label} · aperçu`,category:'Exemple de nouveauté',source:'Démonstration visuelle · aucun changement de données',added:['Nouveau personnage dans le catalogue'],updated:['Données de rotation et de compétences'],removed:[]});localStorage.setItem(key,JSON.stringify(rows.slice(0,100)));}
function dataUpdateBadge(){let rows=[];try{rows=JSON.parse(localStorage.getItem(`astralis:${state.game}:data-journal`)||'[]')}catch{}const latest=rows[0];if(!latest)return '';const token=String(latest.id||latest.at||'');try{if(localStorage.getItem(`astralis:${state.game}:data-seen`)===token)return ''}catch{}return '<i class="rail-update-badge">NOUVEAU</i>';}
function renderDashboardChangeStrip(){let row;try{row=JSON.parse(localStorage.getItem(`astralis:${state.game}:data-journal`)||'[]').find(x=>x.demo)}catch{}return row?`<button class="dashboard-news-strip" data-nav="changelog"><span class="news-strip-mark">✦</span><span><b>Nouveauté · aperçu du journal</b><small>Exemple de changements de personnages et de rotation — démo visuelle.</small></span><i>Voir le journal →</i></button>`:'';}

function renderDashboardWelcome(){
  if(!prefs.dashboardGreeting)return '';
  if(sessionStorage.getItem('astralis:welcome-session')==='seen')return '';
  const hour=new Date().getHours(),salutation=hour<5?'Bonsoir':hour<12?'Bonjour':hour<18?'Bon après-midi':'Bonsoir',traveler=travelerProfile(),profiles=readAssistantProfiles().filter(p=>p?.enabled!==false&&p?.personaCharacter).slice(0,5),roster=companionCharacters();
  const lines=profiles.map((profile,index)=>{const person=roster.find(c=>String(c._id)===String(profile.personaCharacter));if(!person)return '';const voice=COMPANION_VOICES[companionNameKey(person._name)],line=voice?.lore?.[index%Math.max(1,voice.lore.length)]||(['Ta journée est déjà bien remplie ? On choisit une seule priorité et on avance tranquillement.','Je suis là. Dis-moi ce que tu veux préparer, et on s’y met.','Avant de partir, vérifie ton plan : une bonne préparation évite les détours.'][index%3]);return `<article class="dashboard-welcome-line" style="--welcome-accent:${esc(companionAccent(person))}">${img(companionPortrait(person),'',person._name)}<span><b>${esc(profile.companion||person._name)}</b><p>${esc(line.replaceAll('{to}',traveler.name||'Voyageur'))}</p></span></article>`}).join('');
  return `<div class="dashboard-arrival" style="--welcome-accent:${esc(GAMES[state.game].accent||'#b998ff')}" role="dialog" aria-modal="true" aria-label="Accueil Astralis"><div class="dashboard-arrival-backdrop"></div><section class="dashboard-arrival-card"><button type="button" class="dashboard-arrival-close" data-action="dashboard-welcome-close" aria-label="Fermer l’accueil">×</button><div class="arrival-orbit">✦</div><span class="dashboard-kicker">ASTRALIS · ${esc(GAMES[state.game].label)}</span><h2>${salutation}${traveler.name?`, ${esc(traveler.name)}`:''}.</h2><p class="arrival-clock">Il est ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}.</p><div class="arrival-companions">${lines||'<p class="arrival-default">Ton espace est prêt. Tes favoris, objectifs et prochaines activités sont rassemblés ici.</p>'}</div><button type="button" class="button-primary" data-action="dashboard-welcome-close">Entrer dans Astralis <span>→</span></button></section></div>`;
}

function releaseDashboardWelcomeScroll(){const body=document.body;if(Object.hasOwn(body.dataset,'dashboardWelcomeOverflow')){body.style.overflow=body.dataset.dashboardWelcomeOverflow;delete body.dataset.dashboardWelcomeOverflow}}
function dismissDashboardWelcome(modal=document.querySelector('.dashboard-arrival')){if(!modal)return;sessionStorage.setItem('astralis:welcome-session','seen');modal.classList.add('is-leaving');setTimeout(()=>{modal.remove();releaseDashboardWelcomeScroll();if(state.section==='dashboard')renderPageOnly()},240)}
function portalDashboardWelcome(){const nodes=[...document.querySelectorAll('.dashboard-arrival')];if(state.section!=='dashboard'){nodes.forEach(node=>node.remove());releaseDashboardWelcomeScroll();return}if(!nodes.length){releaseDashboardWelcomeScroll();return}const modal=nodes[nodes.length-1];nodes.slice(0,-1).forEach(node=>node.remove());if(modal.parentElement!==document.body)document.body.append(modal);if(!Object.hasOwn(document.body.dataset,'dashboardWelcomeOverflow')){document.body.dataset.dashboardWelcomeOverflow=document.body.style.overflow||'';document.body.style.overflow='hidden'}modal.querySelectorAll('[data-action="dashboard-welcome-close"]').forEach(button=>{button.onclick=event=>{event.preventDefault();event.stopPropagation();dismissDashboardWelcome(modal)}})}

function renderCurrencyWars(){
  const characters=state.catalogs['hsr:character']||[],weapons=state.catalogs['hsr:weapon']||[];
  if(!characters.length&&!state.loaders.has('hsr:character')){loadCatalog('hsr','character',{quiet:true}).then(()=>renderPageOnly());}
  if(!weapons.length&&!state.loaders.has('hsr:weapon')){loadCatalog('hsr','weapon',{quiet:true}).then(()=>renderPageOnly());}
  let plans=[];try{plans=JSON.parse(localStorage.getItem('astralis:hsr:currency-wars')||'[]')}catch{}
  const image=c=>avatarImage('hsr',c),saved=plans.map((plan,index)=>`<article class="cw-plan"><header><div><span class="eyebrow">STRATÉGIE ${String(index+1).padStart(2,'0')}</span><h3>${esc(plan.name)}</h3></div><button class="quiet-btn" data-cw-delete="${index}">Supprimer</button></header><div class="cw-roster">${(plan.members||[]).map(id=>{const c=characters.find(row=>String(row._id)===String(id));return c?`<span>${img(image(c),'',c._name)}<b>${esc(c._name)}</b></span>`:''}).join('')||'<small>Aucun personnage sélectionné</small>'}</div><p>${esc(plan.notes||'Aucune note')}</p></article>`).join('');
  return `<section class="currency-wars-page"><header class="cw-hero"><div><span class="eyebrow">HONKAI: STAR RAIL · MODE STRATÉGIQUE</span><h2>Currency Wars</h2><p>Prépare tes formations, garde tes notes et retrouve rapidement les personnages de ta collection.</p></div><div class="cw-hero-mark">₡</div></header><div class="cw-source-row"><article><span class="eyebrow">GUIDE STRATÉGIQUE</span><h3>Compendium HoYoLAB</h3><p>Le guide officiel permet de filtrer les stratégies par personnages et liens. Il peut demander une session HoYoverse.</p><a class="quiet-btn" href="https://www.hoyolab.com/article/42170819" target="_blank" rel="noopener noreferrer">Source officielle ↗</a></article><article><span class="eyebrow">DONNÉES HSR</span><h3>${characters.length} personnages · ${weapons.length} cônes</h3><p>Roster local actualisé avec les catalogues Nanoka et StarRailStatic. Les données du mode Currency Wars ne sont pas publiées dans leur schéma d’équipement général.</p><button class="quiet-btn" data-action="refresh-data">Actualiser les catalogues</button></article></div><section class="cw-editor"><header><div><span class="eyebrow">CARNET LOCAL</span><h3>Enregistrer une composition</h3></div></header><div class="cw-form"><label>Nom de la stratégie<input id="cw-name" maxlength="60" placeholder="Ex. Équipe de départ"></label><label>Personnages<select id="cw-members" multiple size="6">${characters.map(c=>`<option value="${esc(c._id)}">${esc(c._name)}</option>`).join('')}</select><small>Ctrl + clic pour plusieurs personnages.</small></label><label>Notes, liens de bonds et équipement<textarea id="cw-notes" rows="4" placeholder="Priorité d’achat, équipement, synergies…"></textarea></label><button class="button-primary" data-action="currencywars-save">Enregistrer la stratégie</button></div></section><section class="cw-saved"><header><span class="eyebrow">MES STRATÉGIES</span><b>${plans.length}</b></header><div>${saved||'<p class="dashboard-quiet-empty">Tes stratégies sauvegardées apparaîtront ici.</p>'}</div></section><footer class="cw-attribution">Données de roster : <a href="https://github.com/theBowja/starrail-data" target="_blank" rel="noopener noreferrer">StarRailData / Nanoka</a>. Guide Currency Wars : <a href="https://www.hoyolab.com/article/42170819" target="_blank" rel="noopener noreferrer">HoYoLAB</a>.</footer></section>`;
}

