function namesForCategory(category) { return ({ character: 'PERSONNAGE', weapon: 'ÉQUIPEMENT', artifact: 'SET', material:'OBJET / MATÉRIAU' })[category] || 'FICHE'; }

function addRotationAction(action) {
  const draft = state.builder || Store.teams(state.game).find(team => team.id === action.team);
  if (!draft) return toast('Crée ou modifie une équipe pour dessiner sa rotation.');
  const next = { ...action, count: 1 }; delete next.team;
  draft.rotation ||= [];
  const previous = draft.rotation.at(-1);
  if (previous && (previous.key === next.key || (!previous.key && previous.id === next.id && previous.character === next.character && (previous.code || rotationCode(previous.label)) === next.code))) previous.count = (previous.count || 1) + 1;
  else draft.rotation.push(next);
  if (!state.builder) {
    state.suppressStoreRender = true;
    try { Store.saveTeam(state.game, draft); } finally { state.suppressStoreRender = false; }
  }
  refreshRotationDisplay(draft);
}

function persistTeamIfNeeded(team){if(state.builder)return;state.suppressStoreRender=true;try{Store.saveTeam(state.game,team)}finally{state.suppressStoreRender=false}}
function toggleRotationCombo(teamId){
  const team=state.builder?.id===teamId?state.builder:Store.teams(state.game).find(item=>item.id===teamId);if(!team)return;
  team.rotation||=[];
  const open=state.comboDraft?.teamId===teamId?state.comboDraft:openComboFor(team);
  if(open){team.rotation.push({type:'comboEnd',comboId:open.id,repetitions:open.repetitions});state.comboDraft=null;}
  else{
    if(state.comboDraft){const previous=state.builder?.id===state.comboDraft.teamId?state.builder:Store.teams(state.game).find(item=>item.id===state.comboDraft.teamId);if(previous){previous.rotation.push({type:'comboEnd',comboId:state.comboDraft.id,repetitions:state.comboDraft.repetitions});persistTeamIfNeeded(previous);}}
    const repetitions=Math.max(2,Math.min(99,Number(team.comboRepetitions)||2)),id=crypto.randomUUID();team.rotation.push({type:'comboStart',comboId:id,repetitions});state.comboDraft={teamId,id,repetitions};
  }
  persistTeamIfNeeded(team);const top=window.scrollY,modalScroll=document.querySelector('.team-builder')?.scrollTop||0;render();window.scrollTo(0,top);const modal=document.querySelector('.team-builder');if(modal)modal.scrollTop=modalScroll;
}

function rotationSummary(rotation=[]){let result='',inside=false,separator=' > ';for(const action of rotation){if(action?.type==='comboStart'){const repetitions=Number(action.repetitions)||2;if(result)result+=separator;result+=`${repetitions} [`;inside=true;continue;}if(action?.type==='comboEnd'){result+=']';inside=false;continue;}const code=action.code||rotationCode(action.label),count=Math.max(1,Number(action.count)||1),chunk=`${code}${count>1?count:''}`;if(result&&!result.endsWith('['))result+=separator;result+=chunk;}return result;}

function refreshRotationDisplay(team) {
  const lines=[...document.querySelectorAll('.rotation-line')];
  const line=state.builder?.id===team.id?(document.querySelector('.team-builder .builder-line')||lines.find(node=>node.classList.contains('builder-line'))):lines.find(node=>node.closest('[data-team-id]')?.dataset.teamId===team.id);
  if (line) { line.classList.add('rotation-left-to-right'); line.innerHTML = team.rotation.length ? team.rotation.map((action, index) => renderRotationAction(action, index, team)).join('') : '<span class="rotation-empty">Clique sur les compétences pour construire la séquence.</span>'; }
  for (const button of document.querySelectorAll('.skill-button[data-skill-key]')) {
    if (button.dataset.teamId !== team.id) continue;
    const total = (team.rotation || []).filter(action => action.key === button.dataset.skillKey || (!action.key && action.id === button.dataset.skillId && action.character === button.dataset.characterId && (action.code || rotationCode(action.label)) === button.dataset.skillCode)).reduce((sum, action) => sum + (action.count || 1), 0);
    const badge = button.querySelector('.skill-count');
    if (badge) { badge.textContent = total || ''; badge.hidden = !total; }
    button.classList.toggle('is-selected', total > 0);
  }
}

