function setupDashboardWidgets(){
  const host=document.querySelector('#page-content');if(!host||state.section!=='dashboard')return;
  const key=`astralis:${state.game}:dashboard-order`;let saved=[];try{const parsed=JSON.parse(localStorage.getItem(key)||'[]');saved=Array.isArray(parsed)?parsed:[]}catch{}
  const widgets=[...host.children].filter(node=>node.matches('[data-dashboard-widget]'));
  const ordered=[...widgets].sort((a,b)=>{const ai=saved.indexOf(a.dataset.dashboardWidget),bi=saved.indexOf(b.dataset.dashboardWidget);return (ai<0?999:ai)-(bi<0?999:bi)});
  if(saved.length){const slots=widgets.map(node=>{const mark=document.createComment('dashboard-widget-slot');node.before(mark);return mark});widgets.forEach(node=>node.remove());slots.forEach((mark,index)=>mark.replaceWith(ordered[index]));}
  let widgetPrefs={hidden:[],colors:{}};try{const parsed=JSON.parse(localStorage.getItem(`astralis:${state.game}:dashboard-widget-settings`)||'{}');widgetPrefs={...widgetPrefs,...parsed};if(!Array.isArray(widgetPrefs.hidden))widgetPrefs.hidden=[];if(!widgetPrefs.colors||typeof widgetPrefs.colors!=='object')widgetPrefs.colors={};}catch{}
  ordered.forEach(node=>{node.draggable=true;node.hidden=widgetPrefs.hidden.includes(node.dataset.dashboardWidget);const color=widgetPrefs.colors?.[node.dataset.dashboardWidget];if(color){node.style.borderLeft=`2px solid ${color}`;node.style.setProperty('--widget-accent',color);}});
  if(root.dataset.dashboardDnDBound)return;root.dataset.dashboardDnDBound='true';let dragged=null;
  root.addEventListener('dragstart',event=>{const widget=event.target.closest('#page-content [data-dashboard-widget]');if(!widget)return;dragged=widget;widget.classList.add('dashboard-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',widget.dataset.dashboardWidget)});
  root.addEventListener('dragover',event=>{const target=event.target.closest('#page-content [data-dashboard-widget]');if(!dragged||!target||target===dragged)return;event.preventDefault();const rect=target.getBoundingClientRect(),after=event.clientY>rect.top+rect.height/2;target.parentNode.insertBefore(dragged,after?target.nextSibling:target)});
  root.addEventListener('drop',event=>{if(!dragged)return;event.preventDefault();const order=[...document.querySelectorAll('#page-content > [data-dashboard-widget]')].map(node=>node.dataset.dashboardWidget);localStorage.setItem(key,JSON.stringify(order));dragged.classList.remove('dashboard-dragging');dragged=null;toast('Disposition du tableau de bord enregistrée.')});
  root.addEventListener('dragend',()=>{dragged?.classList.remove('dashboard-dragging');dragged=null});
}

function renderPageOnly(focusSelector=''){
  const host=document.querySelector('#page-content');if(!host)return;
  host.innerHTML=renderPage();if(state.section==='dashboard')setupDashboardWidgets();bindEvents();portalDashboardWelcome();
  hydrateXTimeline(host);
  if(focusSelector){const input=document.querySelector(focusSelector);if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length);}}
}
function hydrateXTimeline(host=document.querySelector('#page-content')){
  if(state.section!=='events'||!host?.querySelector('.twitter-timeline'))return;
  const loadWidgets=()=>window.twttr?.widgets?.load?.(host);
  if(window.twttr)loadWidgets();
  else if(!document.querySelector('script[data-x-widgets]')){const script=document.createElement('script');script.src='https://platform.twitter.com/widgets.js';script.async=true;script.dataset.xWidgets='true';script.onload=loadWidgets;document.head.append(script);}
}

async function hydrateBuilderSlot(index) {
  const id = state.builder.members[index]?.character;
  const character = itemById(state.game, 'character', id);
  if (!character) return;
  try { state.details[`${state.game}:${id}`] = await characterDetails(state.game, character); } catch { /* the role icons remain usable without descriptions */ }
}

async function saveBuilder() {
  const draft = state.builder;
  const members = draft.members.filter(slot => slot.character);
  if (!draft.name.trim()) return toast('Donne un nom à cette équipe.');
  if (!members.length) return toast('Choisis au moins un personnage.');
  const shot = draft.screenshot || '';
  Store.saveTeam(state.game, { ...draft, members, screenshot: shot, updated: Date.now() });
  state.builder = null; render(); toast('Équipe enregistrée avec sa rotation.');
}

function openNote(note=null, target=null){
  const game=target?.game||state.game, character=target?.id?itemById(game,'character',target.id):null;
  state.noteDraft=note?{...note,_editing:true,game}:{id:crypto.randomUUID(),game,title:'',tag:character?'Personnage':'Générale',body:'',target:character?character._id:'',targetName:character?character._name:'',pinned:false};
  renderModal();
}
function openTask(task=null, target=null){
  const game=target?.game||state.game, character=target?.id?itemById(game,'character',target.id):null;
  state.taskDraft=task?{...task,_editing:true,game}:{id:crypto.randomUUID(),game,title:'',category:character?'Personnage':'Build',priority:'Normale',due:'',character:character?character._id:'',characterName:character?character._name:'',done:false};
  renderModal();
}
function createTaskTemplate(key){
  const template=TASK_TEMPLATES[key];if(!template)return;
  const character=state.selected?.category==='character'?itemById(state.game,'character',state.selected.id):null;
  for(const title of template.tasks)Store.saveTask(state.game,{id:crypto.randomUUID(),title,category:template.category,priority:'Normale',due:'',character:character?._id||'',characterName:character?._name||'',done:false,source:key});
  toast(`${template.tasks.length} tâches ajoutées.`);
}

function switchDetailTab(key) {
  document.querySelectorAll('[data-detail-tab]').forEach(button => button.classList.toggle('active', button.dataset.detailTab === key));
  document.querySelectorAll('[data-detail-content]').forEach(content => { content.hidden = content.dataset.detailContent !== key; });
}

