    const data={...Store.exportData(),preferences:prefs,giWorkspace:{sheets:readLocalList(calcKey),farm:readLocalList(farmKey),endgame:readLocalList(endgameKey),builds:readLocalList('astralis:gi:builds'),farmCalendar:readLocalList('astralis:gi:farm-calendar'),farmInventory:(()=>{try{return JSON.parse(localStorage.getItem('astralis:gi:farm-inventory')||'{}')}catch{return {}}})(),ownedArtifacts:giReadOwnedArtifacts(),wishPlan:wishPlan(),assistantProfile:(()=>{try{return JSON.parse(localStorage.getItem('astralis:gi:assistant-profile')||'{}')}catch{return {}}})(),assistantProfiles:readAssistantProfiles(),mediaVideos:readLocalList('astralis:media-videos'),mediaChannels:readLocalList('astralis:media-channels'),skinSplashes:Object.keys(localStorage).filter(k=>k.startsWith('astralis:gi:skin-splash:')).map(k=>[k,localStorage.getItem(k)]),profile:state.giProfile,profileUid:state.profileUid},local:{hsrProfile:state.hsrProfile,galleries,media:[],mediaPlaylist:[]}};
