 try{const response=await fetch(`https://api.github.com/repos/${repo}/releases/latest`,{headers:{Accept:'application/vnd.github+json'},cache:'no-store'});if(!response.ok)return;const release=await response.json(),tag=String(release.tag_name||'').trim();if(!tag||tag===localStorage.getItem('astralis:update-seen-tag')||/^v?75(?:\.|$)/i.test(tag))return;localStorage.setItem('astralis:update-seen-tag',tag);toast(`Mise à jour Astralis disponible : ${tag}. Ouvre les paramètres pour consulter la version.`);}catch{}
