async function runAstralisUpdate(manual=false){
 const button=document.querySelector('[data-action="app-update"]'),status=document.querySelector('[data-app-update-status]');
 if(button)button.disabled=true;if(status)status.textContent='Recherche de la dernière version…';
 try{
  const check=await fetch('/api/app/update',{cache:'no-store'}),info=await check.json();
  if(!check.ok)throw Error(info.error||'Connexion au service de mise à jour impossible.');
  if(info.managed){if(status)status.textContent=info.message;if(manual)toast(info.message);return;}
  if(!info.available){if(status)status.textContent=`Astralis est à jour · ${info.latest||''}`;if(manual)toast('Astralis est déjà à jour.');return;}
  if(status)status.textContent=`Nouvelle version ${info.latest} détectée · installation…`;
  const applied=await fetch('/api/app/update',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),result=await applied.json();
  if(!applied.ok)throw Error(result.error||'Installation de la mise à jour impossible.');
  if(result.updated){if(status)status.textContent='Mise à jour installée · rechargement…';if(manual)toast('Astralis a été mis à jour; rechargement en cours…');setTimeout(()=>location.reload(),900);return;}
  if(status)status.textContent=result.message||'Astralis est à jour.';if(manual)toast(result.message||'Astralis est à jour.');
 }catch(error){if(status)status.textContent=`Vérification impossible · ${error.message||'connexion indisponible'}`;if(manual)toast(`Mise à jour impossible : ${error.message||'connexion indisponible'}`);}
 finally{if(button)button.disabled=false;}
}
setTimeout(()=>runAstralisUpdate(false),1800);




